import threading
import time
import hashlib
import os
import re
import socket
import ipaddress
from urllib.parse import urlparse
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

# Thread-safe session store
class SessionStore:
    def __init__(self):
        self._sessions = {}
        self._lock = threading.Lock()

    def create_session(self, user_id, role):
        token = hashlib.sha256(os.urandom(32)).hexdigest()
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'role': role,
                'created_at': time.time()
            }
        return token

    def get_session(self, token):
        with self._lock:
            session = self._sessions.get(token, None)
            if session:
                return dict(session)  # Return copy
            return None

    def update_role(self, token, new_role):
        with self._lock:
            if token in self._sessions:
                self._sessions[token]['role'] = new_role
                return True
        return False

    def invalidate_session(self, token):
        with self._lock:
            if token in self._sessions:
                del self._sessions[token]
                return True
        return False

sessions = SessionStore()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token:
            return jsonify({'error': 'No session token'}), 401

        # Always check authoritative session store directly
        session = sessions.get_session(token)
        if session is None:
            return jsonify({'error': 'Invalid session'}), 401

        g.role = session['role']
        g.token = token
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    @require_auth
    def decorated(*args, **kwargs):
        if g.role != 'admin':
            return jsonify({'error': 'Admin required'}), 403
        return f(*args, **kwargs)
    return decorated

def _is_disallowed_ip(ip_str):
    """Return True if the IP is private, loopback, link-local, or otherwise reserved."""
    try:
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return True  # Not a valid IP literal; treat cautiously
    return (
        ip.is_private
        or ip.is_loopback
        or ip.is_link_local
        or ip.is_multicast
        or ip.is_reserved
        or ip.is_unspecified
    )

# URL validation for webhook feature
def validate_webhook_url(url):
    """Validate webhook URLs to prevent SSRF by properly parsing the host and
    validating any resolved IP addresses against private/reserved ranges."""
    if not url:
        return False

    # Basic shape check: must be https
    try:
        parsed = urlparse(url)
    except Exception:
        return False

    if parsed.scheme != 'https':
        return False

    # Reject embedded credentials (user:pass@host) which can obscure the real host
    if '@' in parsed.netloc:
        return False

    hostname = parsed.hostname
    if not hostname:
        return False

    # Reject obvious internal hostnames
    if hostname.lower() == 'localhost':
        return False

    # Enforce a sane hostname/path character set
    host_pattern = r'^[a-zA-Z0-9][a-zA-Z0-9\-\.]*[a-zA-Z0-9]$'
    if not re.match(host_pattern, hostname):
        return False

    path = parsed.path or ''
    if path and not re.match(r'^/[a-zA-Z0-9/\-_]*$', path):
        return False

    # If the host is an IP literal, validate it directly.
    try:
        ipaddress.ip_address(hostname)
        return not _is_disallowed_ip(hostname)
    except ValueError:
        pass

    # Resolve the hostname and ensure no resolved address is internal/reserved.
    try:
        addr_infos = socket.getaddrinfo(hostname, None)
    except socket.gaierror:
        return False

    resolved_ips = {info[4][0] for info in addr_infos}
    if not resolved_ips:
        return False
    for ip_str in resolved_ips:
        if _is_disallowed_ip(ip_str):
            return False

    return True

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')

    # Simplified auth (demo)
    if username == 'admin' and password == 'admin_pass_demo':
        token = sessions.create_session(username, 'admin')
        return jsonify({'token': token})
    elif username and password:
        token = sessions.create_session(username, 'user')
        return jsonify({'token': token})
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/demote', methods=['POST'])
@require_admin
def demote_user():
    """Admin demotes a user (or themselves) to regular user"""
    data = request.get_json()
    target_token = data.get('target_token')
    if not target_token:
        return jsonify({'error': 'No target specified'}), 400

    # Update role in session store atomically
    sessions.update_role(target_token, 'user')

    return jsonify({'status': 'demoted'})

@app.route('/revoke', methods=['POST'])
@require_admin
def revoke_session():
    """Admin revokes a session entirely"""
    data = request.get_json()
    target_token = data.get('target_token')
    if not target_token:
        return jsonify({'error': 'No target specified'}), 400

    # Destroy session atomically
    sessions.invalidate_session(target_token)

    return jsonify({'status': 'revoked'})

@app.route('/admin/secrets', methods=['GET'])
@require_admin
def get_secrets():
    return jsonify({'secrets': ['secret_key_1', 'secret_key_2', 'database_password']})

@app.route('/admin/webhook', methods=['POST'])
@require_admin
def set_webhook():
    data = request.get_json()
    url = data.get('url', '')
    if not validate_webhook_url(url):
        return jsonify({'error': 'Invalid webhook URL'}), 400
    return jsonify({'status': 'webhook set', 'url': url})

@app.route('/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({'role': g.role, 'token': g.token})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, threaded=True)
